#!/usr/bin/env python3
"""
refresh-wag-messages.py
Reads your iMessages from the last 7 days, filters out spam/OTPs/marketing,
and updates the iMessage section in week-at-a-glance.html on your Desktop.

Run: python3 ~/Desktop/refresh-wag-messages.py
"""

import sqlite3
import re
import os
from datetime import datetime, timezone, timedelta
from pathlib import Path

# ── Config ────────────────────────────────────────────────────────────────────
HTML_FILE   = Path.home() / "Desktop" / "week-at-a-glance.html"
MESSAGES_DB = Path.home() / "Library" / "Messages" / "chat.db"
DAYS_BACK   = 7   # how many days of messages to scan

# ── Known contacts (add more as you learn who numbers belong to) ──────────────
CONTACTS = {
    "+12705437546": "270-543-7546",
    "+12709913503": "270-991-3503",
    "+12708423555": "Susan Hughes (USDA)",
    # add more: "+1XXXXXXXXXX": "Name",
}

# ── Spam / noise filters ──────────────────────────────────────────────────────
SPAM_SENDERS = {
    "28581",   # Cash App OTP
    "23951",   # Refund Selection spam
    "72975",   # spam URL
    "77098",   # spam URL
    "41350",   # Staples marketing
    "21525",   # Walgreens marketing
    "88683",   # TurboVote
    "34797",   # Waterboy
}

SPAM_PATTERNS = [
    r"^https?://",                          # bare URL messages
    r"unsubscribed from",                   # unsub confirmations
    r"secure code is:",                     # OTP codes (don't surface in calendar)
    r"This code is for you and only you",   # Cash App OTP
    r"attn\.tv/",                           # marketing links
    r"wlgrn\.com/",                         # Walgreens marketing
    r"py\.pl/",                             # spam shortlink
    r"cbnk\.co/",                           # spam shortlink
    r"staples\.attn",                       # Staples marketing
]

SECURITY_SENDERS = {
    "+18334172274",  # Cash App security
}

SECURITY_PATTERNS = [
    r"new device login",
    r"suspicious activity",
    r"unusual sign.?in",
]

def fmt_phone(raw: str) -> str:
    """Return display name or formatted number."""
    if raw in CONTACTS:
        return CONTACTS[raw]
    # format +1XXXXXXXXXX → (XXX) XXX-XXXX
    digits = re.sub(r"\D", "", raw)
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) == 10:
        return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"
    return raw

def is_spam(sender: str, text: str) -> bool:
    if sender in SPAM_SENDERS:
        return True
    text_lower = text.lower()
    for pat in SPAM_PATTERNS:
        if re.search(pat, text_lower):
            return True
    return False

def is_security(sender: str, text: str) -> bool:
    if sender in SECURITY_SENDERS:
        return True
    text_lower = text.lower()
    for pat in SECURITY_PATTERNS:
        if re.search(pat, text_lower):
            return True
    return False

def fetch_messages() -> list[dict]:
    """Pull recent inbound messages from chat.db."""
    cutoff = datetime.now(timezone.utc) - timedelta(days=DAYS_BACK)
    # Apple epoch: Jan 1 2001 00:00:00 UTC = Unix 978307200
    apple_cutoff = int((cutoff.timestamp() - 978307200) * 1e9)

    conn = sqlite3.connect(f"file:{MESSAGES_DB}?mode=ro", uri=True)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("""
        SELECT
            CASE
                WHEN m.text IS NOT NULL AND m.text != '' THEN m.text
                ELSE NULL
            END AS content,
            datetime(m.date/1000000000 + 978307200, 'unixepoch', 'localtime') AS ts,
            h.id AS sender,
            m.is_from_me
        FROM message m
        INNER JOIN handle h ON h.ROWID = m.handle_id
        WHERE m.is_from_me = 0
          AND m.date >= ?
          AND m.text IS NOT NULL AND m.text != ''
          AND m.is_audio_message = 0
          AND m.item_type = 0
        ORDER BY m.date DESC
        LIMIT 100
    """, (apple_cutoff,))
    rows = [dict(r) for r in cur.fetchall()]
    conn.close()
    return rows

def build_card(sender: str, text: str, ts: str, card_type: str, action: str = "") -> str:
    display = fmt_phone(sender)
    # parse ts for display
    try:
        dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
        now = datetime.now()
        if dt.date() == now.date():
            day_label = "Today"
            time_label = dt.strftime("%-I:%M %p")
        elif dt.date() == (now - timedelta(days=1)).date():
            day_label = "Yesterday"
            time_label = dt.strftime("%-I:%M %p")
        else:
            day_label = dt.strftime("%b %-d")
            time_label = dt.strftime("%-I:%M %p")
    except Exception:
        day_label = ""
        time_label = ts

    # truncate long messages
    preview = text.strip().replace('"', '&quot;').replace('<', '&lt;').replace('>', '&gt;')
    if len(preview) > 180:
        preview = preview[:177] + "…"

    tag_class = "security" if card_type == "imsg-alert" else ""
    action_html = f'\n        <div class="ic-sub">{action}</div>' if action else ""

    return f"""
    <div class="inbox-card {card_type}">
      <div class="ic-body">
        <div class="ic-from">
          {display}
          <span class="source-tag {tag_class}">iMessage · {day_label}</span>
        </div>
        <div class="ic-text">"{preview}"</div>{action_html}
        <div class="ic-time">{time_label}</div>
      </div>
    </div>"""

def generate_cards(messages: list[dict]) -> tuple[str, str]:
    """Returns (cards_html, timestamp_str)."""
    cards = []
    seen_senders = set()

    for msg in messages:
        sender = msg["sender"]
        text   = msg["content"] or ""
        ts     = msg["ts"]

        if is_spam(sender, text):
            continue

        if is_security(sender, text):
            card = build_card(
                sender, text, ts, "imsg-alert",
                action="If this wasn't you, check the app immediately"
            )
            cards.append(card)
            continue

        # dedupe: only show the most recent message per sender
        if sender in seen_senders:
            continue
        seen_senders.add(sender)

        cards.append(build_card(sender, text, ts, "imsg"))

    if not cards:
        cards = ['    <div class="inbox-card"><div class="ic-body"><div class="ic-text" style="color:#bbb;">No new actionable messages in the last 7 days.</div></div></div>']

    now_str = datetime.now().strftime("%b %-d, %-I:%M%p").lower().replace("am", "am").replace("pm", "pm")
    return "\n".join(cards), now_str

def update_html(cards_html: str, checked_at: str):
    """Replace the iMessage cards block and last-checked timestamp in the HTML."""
    html = HTML_FILE.read_text(encoding="utf-8")

    # Update last-checked timestamp
    html = re.sub(
        r'(id="last-checked">).*?(</span>)',
        rf'\1Last checked: {checked_at}\2',
        html
    )

    # Replace everything between the iMessage cards div tags
    html = re.sub(
        r'(<div class="inbox-cards" id="imessage-cards">).*?(</div>\s*\n*\s*<!-- WEEK GRID -->)',
        rf'\1{cards_html}\n\n  </div>\n\n<!-- WEEK GRID -->',
        html,
        flags=re.DOTALL
    )

    HTML_FILE.write_text(html, encoding="utf-8")
    print(f"✓ Updated {HTML_FILE}")
    print(f"  Last checked: {checked_at}")
    print(f"  Cards written: {cards_html.count('inbox-card')}")

def main():
    if not MESSAGES_DB.exists():
        print("✗ Cannot find Messages database.")
        print("  Make sure Full Disk Access is granted for Terminal/Python.")
        return

    if not HTML_FILE.exists():
        print(f"✗ HTML file not found: {HTML_FILE}")
        return

    print("Reading messages…")
    try:
        messages = fetch_messages()
    except Exception as e:
        print(f"✗ Could not read messages: {e}")
        return

    print(f"  {len(messages)} messages in the last {DAYS_BACK} days")
    cards_html, checked_at = generate_cards(messages)
    update_html(cards_html, checked_at)
    print("  Done — refresh your browser to see updates.")

if __name__ == "__main__":
    main()
